static class RebirthRepairOriginalCorrection {internal class Receipt {internal Guid Operation;internal bool Admitted,Cancelled,BaseOnly,BaseOnlyConfirmed;internal string Input="input",Before="output",Owner="owner",Creation="creation",World="world";internal int Deaths=2;}public static bool ValidNativeOutput(Receipt r,ItemValue output)=>output.UseTimes==10;}
