static class RebirthSkillAwardService {public static HashSet<string> Receipts=new HashSet<string>();public static int Awards;public static bool Durable=true;public static bool TryAwardMigratedTrainingEvidence(EntityPlayer p,RebirthSkillTrainingEvidence e,out object ignored,out float gained,out float attribute){ignored=null;gained=attribute=0;if(e.SkillId!="skill.gunsmithing"||Math.Abs(e.DiscreteRawAward-.21875f)>.00001f||e.CreditedWork!=1||e.AssistanceMultiplier!=1||!e.AuthoritativeSuccess||!e.DurableReceiptId.StartsWith("repair-original:"))throw new Exception("original profile/reward binding changed");if(Receipts.Add(e.DurableReceiptId))Awards++;return Durable;}}
